class Book:
    def __init__(self, title, author):
        self.title = title
        self.author = author
        self.available = True

class Member:
    def __init__(self, name):
        self.name = name
        self.borrowed = []

class Library:
    def __init__(self):
        self.books = []
        self.members = []

    def add_book(self, book):
        self.books.append(book)

    def register_member(self, member):
        self.members.append(member)

    def lend_book(self, member_name, book_title):
        member = next((m for m in self.members if m.name == member_name), None)
        book = next((b for b in self.books if b.title == book_title), None)
        if member and book and book.available:
            book.available = False
            member.borrowed.append(book.title)
            return f'Lent {book_title} to {member_name}'
        return 'Lending failed'

    def return_book(self, member_name, book_title):
        member = next((m for m in self.members if m.name == member_name), None)
        book = next((b for b in self.books if b.title == book_title), None)
        if member and book and not book.available:
            book.available = True
            if book_title in member.borrowed:
                member.borrowed.remove(book_title)
            return f'Returned {book_title} from {member_name}'
        return 'Return failed'
